return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n == 0 || n % 100 >= 2 && n % 100 <= 19) ? 1 : 2);','language'=>'ro_RO','project-id-version'=>'Babilim 1.2.1','pot-creation-date'=>'2026-11-09T07:54:34+00:00','po-revision-date'=>'2026-11-09T07:54:34+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'Trimise când apeși Activează Babilim și din nou dacă site-ul trebuie să se înregistreze din nou: URL-ul site-ului tău, versiunile de WordPress, PHP și Babilim, limba site-ului tău și limbile utilizate pe acesta, precum și o cheie publică generată pentru acest site.','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'Trimise la fiecare verificare: lista pluginurilor și temelor instalate, cu starea oricărei traduceri Babilim instalate pentru acestea, limbile utilizate și coduri de diagnosticare scurte.','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'Fiecare solicitare include URL-ul site-ului tău, iar token-ul de acces al site-ului este inclus ori de câte ori serviciul are nevoie de el.','What Babilim sends to the service'=>'Ce trimite Babilim către serviciu','Your site\'s URL'=>'URL-ul site-ului tău','WordPress version'=>'Versiunea WordPress','PHP version'=>'Versiunea PHP','Babilim version'=>'Versiunea Babilim','Your site\'s language'=>'Limba site-ului tău','Languages in use on your site'=>'Limbi utilizate pe site-ul tău','A public key for this site'=>'O cheie publică pentru acest site','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'O cheie publică generată pentru acest site, folosită pentru a dovedi că solicitările provin cu adevărat de la acest site. Se trimite doar jumătatea publică; jumătatea privată rămâne pe site-ul tău.','Installed plugins and themes'=>'Pluginuri și teme instalate','For every installed plugin and theme: its name (slug), version, text domain, whether it is listed on WordPress.org, and the languages it already includes. For each Babilim translation you have installed: which version it is, when it was last checked, and whether it passed its file check.'=>'Pentru fiecare plugin și temă instalată: numele (slug), versiunea, text domain, dacă este listat pe WordPress.org și limbile pe care le include deja. Pentru fiecare traducere Babilim instalată de tine: ce versiune este, când a fost verificată ultima dată și dacă a trecut verificarea fișierelor.','Source files (only if you confirm an upload)'=>'Fișiere sursă (doar dacă confirmi o încărcare)','Diagnostic codes'=>'Coduri de diagnosticare','Up to 20 short diagnostic codes (for example, a translation file that failed its check), each with the plugin or theme, the language and the time it happened. They never contain any text from your site or any translated text.'=>'Până la 20 de coduri de diagnosticare scurte (de exemplu, un fișier de traducere care a eșuat la verificare), fiecare cu pluginul sau tema, limba și momentul în care s-a întâmplat. Nu conțin niciodată text de pe site-ul tău și nici text tradus.','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d site din această rețea este setat să șteargă identitatea sa Babilim la ștergerea pluginului. Licența plătită asociată acelui site nu ar mai putea fi restaurată automat; ar trebui să contactați Asistență Babilim la %2$s. Pentru a păstra identitatea, apăsați Anulează, debifați „Șterge toate datele Babilim la dezinstalare” în Setări Babilim ale acelui site și dezactivați din nou. Dezactivați oricum?' . "\0" . '%1$d site-uri din această rețea sunt setate să șteargă identitatea lor Babilim la ștergerea pluginului. Licența plătită asociată acelor site-uri nu ar mai putea fi restaurată automat; ar trebui să contactați Asistență Babilim la %2$s. Pentru a păstra identitățile, apăsați Anulează, debifați „Șterge toate datele Babilim la dezinstalare” în Setări Babilim ale fiecărui site și dezactivați din nou. Dezactivați oricum?' . "\0" . '%1$d de site-uri din această rețea sunt setate să șteargă identitatea lor Babilim la ștergerea pluginului. Licența plătită asociată acelor site-uri nu ar mai putea fi restaurată automat; ar trebui să contactați Asistență Babilim la %2$s. Pentru a păstra identitățile, apăsați Anulează, debifați „Șterge toate datele Babilim la dezinstalare” în Setări Babilim ale fiecărui site și dezactivați din nou. Dezactivați oricum?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s nu e nimic de făcut.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Alegeți limba.','%d failed'=>'%d eșuat' . "\0" . '%d eșuate' . "\0" . '%d eșuate','%d not yet tried'=>'%d neîncercat încă' . "\0" . '%d neîncercate încă' . "\0" . '%d neîncercate încă','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d raport așteaptă. „Partajează întotdeauna” și „Nu partaja” se aplică tuturor.' . "\0" . '%d rapoarte așteaptă. „Partajează întotdeauna” și „Nu partaja” se aplică tuturor.' . "\0" . '%d de rapoarte așteaptă. „Partajează întotdeauna” și „Nu partaja” se aplică tuturor.','%d skipped'=>'%d omis' . "\0" . '%d omise' . "\0" . '%d omise','%d succeeded'=>'%d reușit' . "\0" . '%d reușite' . "\0" . '%d reușite','%d to install'=>'%d de instalat' . "\0" . '%d de instalat' . "\0" . '%d de instalat','(a public key generated for this site)'=>'(o cheie publică generată pentru acest site)','(detected)'=>'(detectat)','(generic codes and coordinates only)'=>'(doar coduri generice și coordonate)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'O curățare a fost întreruptă la %1$s: %2$s. Nu s-a șters nimic.','A file in the component could not be read, so it was not packaged.'=>'Un fișier din componentă nu a putut fi citit, deci nu a fost împachetat.','A host that serves only one PHP request at a time cannot complete this step.'=>'O gazdă care servește o singură cerere PHP la un moment dat nu poate finaliza acest pas.','A part of the upload kept failing, so the upload was cancelled.'=>'O parte a încărcării a eșuat în mod repetat, așa că încărcarea a fost anulată.','A translation cannot be requested for that locale on this site right now.'=>'În acest moment nu se poate solicita o traducere pentru această limbă pe acest site.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'O scriere în indexul de traduceri a intrat în conflict cu o altă solicitare la %1$s (%2$s) și nu a fost aplicată; a fost păstrată cea mai recentă versiune.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'O scriere în indexul de traduceri la %1$s (%2$s) nu a putut fi finalizată și nu a fost aplicată (%3$s).','Account'=>'Cont','Add another language'=>'Adaugă încă o limbă','Advanced'=>'Avansate','All'=>'Toate','All free-plan slots for this site are used'=>'Toate sloturile din planul gratuit pentru acest site sunt utilizate','All languages'=>'Toate limbile','Already in WordPress core'=>'Deja în nucleul WordPress','Already installed.'=>'Deja instalat.','Always share'=>'Partajează întotdeauna','Another installation is running; try again in a moment.'=>'Rulează o altă instalare; încercați din nou peste un moment.','Automatic installs'=>'Instalări automate','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Instalările automate sunt acum dezactivate; reactivați-le din setări dacă doriți.','Available'=>'Disponibile','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Traducerile disponibile pot fi instalate cu un singur clic, iar cele lipsă pot fi solicitate. Cât timp instalările automate sunt activate, traducerile pe care serviciul le listează ca disponibile pentru limbile pe care le gestionezi sunt instalate în timpul sincronizării de două ori pe zi.','Available · %s'=>'Disponibil · %s','Babilim'=>'Babilim','Babilim Settings'=>'Setări Babilim','Babilim adds translations for every language checked here.'=>'Babilim adaugă traduceri pentru fiecare limbă bifată aici.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim nu a putut confirma un dosar temporar în afara site-ului, așa că componenta nu a fost împachetată și nu s-a încărcat nimic. Definiți BABILIM_TEMP_DIR în wp-config.php ca un dosar care poate fi scris, situat în afara rădăcinii web (de exemplu un dosar lângă directorul public al site-ului, nu în interiorul lui), sau cereți unul furnizorului de găzduire.','Babilim could not finish checking this site.'=>'Babilim nu a putut termina verificarea acestui site.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim nu a putut finaliza activarea (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim nu a putut finaliza verificarea acestui site (serviciul nu l-a putut contacta înapoi). Înregistrarea este suspendată.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim nu a putut verifica acest site, așa că nu se descarcă și nu se instalează nimic până când verificarea reușește.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim nu a putut verifica acest site, așa că nu se descarcă și nu se instalează nimic.','Babilim gets translations from the Babilim service for the plugins and themes on this site that have none for your language, and installs the ones your service plan covers.'=>'Babilim obține de la Serviciul Babilim traduceri pentru pluginurile și temele de pe acest site care nu au niciuna pentru limba ta și le instalează pe cele acoperite de planul tău de servicii.','Babilim has not been enabled for this site yet.'=>'Babilim nu a fost încă activat pentru acest site.','Babilim has not installed any translation for this language.'=>'Babilim nu a instalat nicio traducere pentru această limbă.','Babilim hit an error. Share an error report?'=>'Babilim a întâmpinat o eroare. Partajezi un raport de eroare?','Babilim installed %d translation automatically since your last visit.'=>'Babilim a instalat automat %d traducere de la ultima vizită.' . "\0" . 'Babilim a instalat automat %d traduceri de la ultima vizită.' . "\0" . 'Babilim a instalat automat %d de traduceri de la ultima vizită.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim este dezactivat. Nu se mai trimite nimic; traducerile deja instalate continuă să funcționeze.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim este activat: acest site este verificat și a fost găsită %d componentă.' . "\0" . 'Babilim este activat: acest site este verificat și au fost găsite %d componente.' . "\0" . 'Babilim este activat: acest site este verificat și au fost găsite %d de componente.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim activează și verifică acest site… (ultima încercare: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim activează și verifică acest site… Reîncărcați această pagină sau așteptați încheierea verificării programate.','Babilim is not enabled.'=>'Babilim nu este activat.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim este setat să șteargă identitatea acestui site la ștergerea pluginului. Licența plătită asociată acestui site nu ar mai putea fi restaurată automat; ar trebui să contactați Asistență Babilim la %s. Pentru a păstra identitatea, apăsați Anulează, debifați „Șterge toate datele Babilim la dezinstalare” în Setări Babilim și dezactivați din nou. Dezactivați oricum?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim a rămas fără timp pentru acest pas și va continua la următoarea verificare.','Babilim settings'=>'Setări Babilim','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Sincronizarea Babilim este amânată temporar de serviciu (limită de cereri); va încerca din nou după %s.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim a fost actualizat cât timp această încărcare era în așteptare. Pachetul vechi a fost eliminat; confirmați din nou încărcarea.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim va încărca aceste fișiere din %1$s (versiunea %2$s): toate fișierele .php și .js, toate fișierele block.json, precum și readme.txt, readme.md, style.css și theme.json din dosarul său principal. Acestea sunt folosite pentru a găsi textul care trebuie tradus și pentru a identifica pluginul sau tema.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest nu este disponibil: %s','Back'=>'Înapoi','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Ați cumpărat anterior o licență pentru acest domeniu? Introduceți codul de restaurare primit la finalizarea plății.','Broken placeholder'=>'Substituent defect','Build'=>'Versiune de compilare','Built'=>'Generat','Bulk actions apply only to the selected language of each selected component.'=>'Acțiunile în masă se aplică doar limbii selectate a fiecărei componente selectate.','Bulk actions apply to every matching language of each selected component.'=>'Acțiunile în masă se aplică fiecărei limbi potrivite a fiecărei componente selectate.','Bulk download:'=>'Descărcare în masă:','Bulk request:'=>'Solicitare în masă:','Bulk update:'=>'Actualizare în masă:','Bundled with the plugin'=>'Inclus în plugin','Bundled with the theme'=>'Inclus în temă','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Dacă faceți clic pe Activează, sunteți de acord să trimiteți informațiile enumerate mai sus către Babilim.','By continuing you confirm that you have the right to upload this component.'=>'Continuând, confirmați că aveți dreptul de a încărca această componentă.','Cancel'=>'Anulează','Category'=>'Categorie','Check again'=>'Verifică din nou','Check again now'=>'Verifică din nou acum','Checkout is not available for this site right now.'=>'Plata nu este disponibilă momentan pentru acest site.','Choose'=>'Alege','Choose a category…'=>'Alege o categorie…','Choose a language'=>'Alegeți o limbă','Choose a language…'=>'Alege o limbă…','Clear filters'=>'Șterge filtrele','Close'=>'Închide','Component'=>'Componentă','Confirm'=>'Confirmă','Conflicting keys'=>'Chei în conflict','Continue'=>'Continuă','Continue next batch (%d left)'=>'Continuă cu lotul următor (mai sunt %d)','Continuing…'=>'Se continuă…','Could not back up %s before replacing it.'=>'Nu s-a putut face o copie de rezervă pentru %s înainte de înlocuire.','Could not create the package archive.'=>'Arhiva pachetului nu a putut fi creată.','Could not determine active components; the existing merged index was left unchanged.'=>'Componentele active nu au putut fi determinate; indexul combinat existent a rămas neschimbat.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Pluginurile/temele instalate nu au putut fi determinate; curățarea a fost omisă, nimic nu a fost șters.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Lista completă de localizări WordPress.org nu a putut fi încărcată de la serviciu, așa că momentan nu se poate adăuga nicio altă limbă.','Could not move %s into place.'=>'Nu s-a putut muta %s la locul său.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Indexul combinat pentru „%s” nu a putut fi mutat la locul lui; indexul servit anterior (dacă exista) a fost eliminat, nu lăsat pe jumătate actualizat. Niciun supliment pentru domeniul implicit nu este servit pentru această localizare până la următoarea reconstruire reușită.','Could not open zip: %s'=>'Nu s-a putut deschide zip-ul: %s','Could not prepare %s for rollback.'=>'Nu s-a putut pregăti %s pentru revenirea la versiunea anterioară.','Could not read %s back after moving it into place.'=>'Nu s-a putut citi %s după mutarea la locul său.','Could not read: %s'=>'Nu s-a putut citi: %s','Could not restore the purchase: %s'=>'Achiziția nu a putut fi restaurată: %s','Could not show a new restore code: %s'=>'Nu s-a putut afișa un nou cod de restaurare: %s','Could not stage %s'=>'Nu s-a putut pregăti %s','Could not stage default/%s'=>'Nu s-a putut pregăti default/%s','Could not start checkout: %s'=>'Nu s-a putut iniția plata: %s','Could not verify entry count for %s'=>'Nu s-a putut verifica numărul de intrări pentru %s','Could not write the downloaded package to disk.'=>'Pachetul descărcat nu a putut fi scris pe disc.','Could not write the staged merged index.'=>'Indexul combinat pregătit nu a putut fi scris.','Current translation'=>'Traducerea curentă','Custom overrides'=>'Suprascrieri personalizate','Danger zone'=>'Zonă periculoasă','Default supplement entry count mismatch.'=>'Numărul de intrări din suplimentul pentru domeniul „default” nu corespunde.','Delete all Babilim data on uninstall'=>'Șterge toate datele Babilim la dezinstalare','Disable Babilim'=>'Dezactivează Babilim','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Dezactivezi Babilim? Traducerile instalate sunt păstrate, dar nu vor mai rula verificări sau descărcări.','Don\'t share'=>'Nu partaja','Download'=>'Descarcă','Downloaded and installed.'=>'Descărcat și instalat.','Downloading…'=>'Se descarcă…','Downloads: %1$d/%2$d (%3$s)'=>'Descărcări: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Contribuția proprie a fiecărei componente la suplimentul pentru domeniul implicit al fiecărei limbi, partajat între componente.','Enable Babilim'=>'Activează Babilim','Enabling…'=>'Se activează…','English (United States)'=>'Engleză (Statele Unite)','Entries'=>'Intrări','Entry count mismatch for %s'=>'Numărul de intrări nu corespunde pentru %s','Error reports'=>'Rapoarte de eroare','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Fiecare localizare folosită pe acest site (localizarea site-ului, pachetele de limbă instalate, localizările utilizatorilor și cele adăugate manual). Nicio localizare nu este tratată diferit de alta.','Excluded'=>'Exclus','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Fișierele cu alte nume sau extensii nu sunt incluse, la fel nici dosarele uploads, cache, logs, backup, data, vendor, node_modules și languages, fișierele ascunse sau fișierele ale căror nume corespund unor secrete uzuale (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Fișierele de cod pot totuși conține text sau date pe care nu ați dori să le partajați; verificați-le dacă nu sunteți sigur. Serviciul elimină din nou aceleași tipuri de fișiere la primire.','Fills in missing translations for the plugins and themes already installed on your site.'=>'Completează traducerile lipsă pentru pluginurile și temele deja instalate pe site-ul tău.','Free'=>'Gratuit','Free-plan slots'=>'Sloturi din planul gratuit','General'=>'Generale','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Dacă este activată, dezinstalarea șterge și identitatea acestui site. Licența plătită asociată acestui site nu va mai putea fi restaurată automat ulterior; ar trebui să contactați Asistență Babilim la %s pentru a o recupera.','Included'=>'Inclus','Included in index'=>'Inclus în index','Install available translations automatically'=>'Instalează automat traducerile disponibile','Installed'=>'Instalate','Installed translations are kept, but no further checks or downloads will run.'=>'Traducerile instalate sunt păstrate, dar nu vor mai rula verificări sau descărcări.','Installed · %s'=>'Instalat · %s','Installed · built for %1$s, this site has %2$s'=>'Instalată · creată pentru %1$s, acest site are %2$s','Installed · built for %s'=>'Instalată · creată pentru %s','Installed · built for %s, new version failed'=>'Instalat · creat pentru %s, versiunea nouă a eșuat','Installed · built for %s, new version scheduled'=>'Instalată · creată pentru %s, versiune nouă programată','Installed · built for %s, translating the new version…'=>'Instalată · creată pentru %s, se traduce versiunea nouă…','Installed · built for %s; this plugin or theme is no longer covered by the site\'s service plan'=>'Instalat · creat pentru %s; acest plugin sau această temă nu mai este acoperit(ă) de planul de servicii al site-ului','Installed · built for a different version'=>'Instalată · creată pentru o altă versiune','Installed · built for a different version, new version failed'=>'Instalat · creat pentru o altă versiune, versiunea nouă a eșuat','Installed · built for a different version, new version scheduled'=>'Instalată · creată pentru o altă versiune, versiune nouă programată','Installed · built for a different version, translating the new version…'=>'Instalată · creată pentru o altă versiune, se traduce versiunea nouă…','Installed · built for a different version; this plugin or theme is no longer covered by the site\'s service plan'=>'Instalat · creat pentru o altă versiune; acest plugin sau această temă nu mai este acoperit(ă) de planul de servicii al site-ului','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Este stocată de furnizorul de găzduire al serviciului și procesată de modele AI pentru a produce traducerea.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Păstrează suprascrierile mele de traducere la ștergerea completă a datelor sau la dezinstalarea acestui plugin.','Language'=>'Limbă','Language:'=>'Limbă:','Languages'=>'Limbi','Languages found on this site: %s.'=>'Limbi găsite pe acest site: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Ultima curățare la %1$s: %2$d marcate recent, %3$d fișier(e) șterse, %4$d înregistrare(ări) eliminate.','Maintenance'=>'Întreținere','Maintenance status is not available right now.'=>'Starea mentenanței nu este disponibilă momentan.','Manifest unavailable: %s'=>'Manifest indisponibil: %s','Negation reversed'=>'Negație inversată','No'=>'Nu','No build is available to download for this locale.'=>'Nu este disponibilă nicio versiune de descărcat pentru această localizare.','No cleanup has run yet.'=>'Nu a fost efectuată încă nicio curățare.','No components match these filters. %s'=>'Nicio componentă nu corespunde acestor filtre. %s','No components synced yet.'=>'Nicio componentă sincronizată încă.','No installed translation matches.'=>'Nicio traducere instalată nu corespunde.','No language is managed yet.'=>'Nicio limbă nu este gestionată încă.','No pending challenge for this nonce.'=>'Nu există nicio provocare în așteptare pentru acest nonce.','No pending challenge to verify.'=>'Nu există nicio provocare în așteptare de verificat.','No plugins or themes found.'=>'Nu s-au găsit pluginuri sau teme.','No previous build to roll back to.'=>'Nu există o versiune build anterioară la care să se revină.','No record for %s'=>'Nu există nicio înregistrare pentru %s','No site id is on file to rotate a token for.'=>'Nu există niciun ID de site înregistrat pentru care să se rotească un token.','No — component inactive'=>'Nu — componenta este inactivă','No — component removed'=>'Nu — componenta a fost eliminată','No — installed version differs from the active one'=>'Nu — versiunea instalată diferă de cea activă','Not a valid server_build_id: %s'=>'server_build_id nu este valid: %s','Not covered by the free service plan'=>'Nu este acoperit de planul de servicii gratuit','Not installed'=>'Neinstalat','Not registered yet'=>'Încă neînregistrat','Not supported'=>'Nesuportat','Not verified'=>'Neverificat','Note (optional)'=>'Notă (opțional)','Nothing to choose.'=>'Nimic de ales.','Nothing to confirm.'=>'Nimic de confirmat.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Dezactivat implicit: ștergerea pluginului păstrează identitatea acestui site, astfel încât o reinstalare o poate reutiliza.','One or more served files no longer match the manifest.'=>'Unul sau mai multe fișiere servite nu mai corespund manifestului.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Achiziție unică pentru acest site: %1$s %2$s. Include toate actualizările viitoare ale traducerilor. Plata este gestionată de Paddle într-o filă nouă.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Doar un administrator de rețea poate face acest lucru, deoarece modifică fișiere de traducere partajate de toate site-urile din această rețea.','Only plugins and themes can be packaged.'=>'Doar pluginurile și temele pot fi împachetate.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Doar când confirmați o încărcare pentru un plugin sau o temă care nu se află pe WordPress.org: toate fișierele .php și .js, toate fișierele block.json, precum și readme.txt, readme.md, style.css și theme.json din dosarul principal al componentei, ca zip, după ce fișierele care corespund unor secrete uzuale sunt excluse.','Open Babilim settings'=>'Deschide Setări Babilim','Original language'=>'Limba originală','Original string'=>'Șirul original','Paid'=>'Cu plată','Partner'=>'Partener','Please check that your site can be reached from the internet, then try again.'=>'Verificați că site-ul dumneavoastră este accesibil de pe internet, apoi încercați din nou.','Please choose a category for this report.'=>'Alege o categorie pentru acest raport.','Plugin'=>'Plugin','Plugin · %s'=>'Plugin · %s','Plugins'=>'Pluginuri','Preview'=>'Previzualizează','Purchase restored. This site is now licensed.'=>'Achiziția a fost restaurată. Acest site este acum licențiat.','Re-parsed entry count did not match the built index.'=>'Numărul de intrări reanalizate nu corespunde cu indexul construit.','Re-verify'=>'Verifică din nou','Rebuild index now'=>'Reconstruiește indexul acum','Refusing to write outside the Babilim language-file directory.'=>'Se refuză scrierea în afara directorului de fișiere de limbă Babilim.','Registration response was missing required fields.'=>'Răspunsul la înregistrare nu conținea câmpurile obligatorii.','Registration restarted.'=>'Înregistrarea a fost repornită.','Remove'=>'Elimină','Remove everything Babilim installed'=>'Elimină tot ce a instalat Babilim','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Elimini tot ce a instalat Babilim? Aceasta șterge fiecare fișier de limbă instalat de Babilim pentru toate pluginurile și temele de pe acest site.','Remove the %2$s translation of %1$s from this site?'=>'Elimini traducerea %2$s pentru %1$s de pe acest site?','Removed %d installed component.'=>'A fost eliminată %d componentă instalată.' . "\0" . 'Au fost eliminate %d componente instalate.' . "\0" . 'Au fost eliminate %d de componente instalate.','Removed after a failed integrity check'=>'Eliminat după o verificare de integritate eșuată','Removed.'=>'Eliminat.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Elimină fiecare fișier de limbă instalat de Babilim pentru toate pluginurile și temele de pe acest site.','Report a problem'=>'Raportează o problemă','Report translation'=>'Raportează traducerea','Request newer translation'=>'Solicită o traducere mai nouă','Request translation'=>'Solicită traducerea','Requestable'=>'Poate fi solicitat','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Solicitarea unei traduceri plasează acest plugin sau această temă pe unul dintre sloturile planului de servicii gratuit pentru acest site (limita este %1$d pentru teme și %2$d pentru pluginuri), dacă nu are deja unul. Un slot rămâne ocupat, iar o traducere eșuată nu îl eliberează.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Solicitarea unei traduceri plasează acest plugin sau această temă pe unul dintre sloturile planului de servicii gratuit pentru acest site, dacă nu are deja unul. Un slot rămâne ocupat, iar o traducere eșuată nu îl eliberează.','Requesting…'=>'Se solicită…','Restart registration'=>'Repornește înregistrarea','Restore code'=>'Cod de restaurare','Restore purchase'=>'Restaurează achiziția','Retry request'=>'Reîncearcă solicitarea','Roll back'=>'Revino la versiunea anterioară','Roll back and report'=>'Revino la versiunea anterioară și raportează','Roll back and send report'=>'Revino la versiunea anterioară și trimite raportul','Roll back the %2$s translation of %1$s to the previous build?'=>'Reveniți la versiunea anterioară a traducerii %2$s pentru %1$s?','Rolled back and reported.'=>'S-a revenit și s-a raportat.','Rolled back to the previous build.'=>'S-a revenit la versiunea anterioară.','Rolled back, but the report could not be sent: %s'=>'S-a revenit, dar raportul nu a putut fi trimis: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Revenirea la versiunea anterioară ar suprascrie „%1$s” (%2$s), care este acum servit pentru o altă componentă instalată (%3$s); nu s-a modificat nimic.','Rotate-token response was missing site_token.'=>'Răspunsului de rotire a tokenului îi lipsea site_token.','Save changes'=>'Salvează modificările','Scheduled, waiting to be processed'=>'Programată, în așteptarea procesării','Search'=>'Caută','Search components'=>'Caută componente','Search the installed translations'=>'Caută în traducerile instalate','Select all'=>'Selectează tot','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Selectează mai puține componente: cel mult %1$d operațiuni per rulare (ai selectat %2$d).','Send report'=>'Trimite raportul','Service plan'=>'Plan de servicii','Settings'=>'Setări','Share error reports'=>'Partajează rapoartele de eroare','Share this report'=>'Partajează acest raport','Show a new restore code'=>'Afișează un nou cod de restaurare','Show the "Report translation" entry in the admin toolbar'=>'Afișează intrarea „Raportează traducerea” în bara de instrumente de administrare','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'O parte din textul acestei componente este codat direct în sursă de autorul ei și nu poate fi tradusă printr-un pachet de limbă.','Status'=>'Stare','Status unknown'=>'Stare necunoscută','String context'=>'Contextul șirului','Suggested translation'=>'Traducere sugerată','Supplementary translation index'=>'Index de traduceri suplimentare','Supplementary translation index rebuilt.'=>'Indexul suplimentar de traduceri a fost reconstruit.','Supplementary translation maintenance'=>'Mentenanța indexului suplimentar de traduceri','Supplementary translations'=>'Traduceri suplimentare','Sweep aborted without orphaning anything: %s.'=>'Curățarea a fost oprită fără a lăsa nimic orfan: %s.','Sweep complete: %d file deleted.'=>'Scanare finalizată: %d fișier șters.' . "\0" . 'Scanare finalizată: %d fișiere șterse.' . "\0" . 'Scanare finalizată: %d de fișiere șterse.','Sweep now'=>'Scanează acum','Sync complete.'=>'Sincronizare finalizată.','Thank you. Your report was sent.'=>'Mulțumim. Raportul tău a fost trimis.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Această componentă nu este instalată pe acest site, deci nu se poate solicita o traducere pentru ea.','That does not look like a restore code.'=>'Acesta nu pare a fi un cod de restaurare.','That is not a valid WordPress locale code. Nothing was saved.'=>'Acesta nu este un cod de localizare WordPress valid. Nu s-a salvat nimic.','That is not a valid build identifier.'=>'Acesta nu este un identificator de versiune build valid.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Acel ecran de încărcare era depășit: de atunci a fost pregătită o altă încărcare. Nu a fost trimis nimic. Verifică-o pe cea curentă din Listă de traduceri.','The change could not be recorded in the translation index; please try again.'=>'Modificarea nu a putut fi înregistrată în indexul de traduceri; încercați din nou.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Curățarea a rulat, dar unele modificări nu au putut fi înregistrate în indexul de traduceri; următoarea curățare le va reîncerca.','The component has no files that can be uploaded.'=>'Componenta nu are fișiere care pot fi încărcate.','The component is not inside the plugins or themes directory.'=>'Componenta nu se află în directorul pluginurilor sau al temelor.','The component\'s main file was not found.'=>'Fișierul principal al componentei nu a fost găsit.','The download response was missing a usable location.'=>'Răspunsului de descărcare îi lipsea o locație utilizabilă.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Intrarea deschide un panou pentru a căuta traducerile instalate de Babilim pe acest site și a raporta una dintre ele.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Câmpul „%1$s” este prea lung: are %2$d caractere, iar limita este %3$d. Nu s-a trimis nimic; te rugăm să îl scurtezi și să încerci din nou.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Planul de servicii gratuit oferă fiecărui site un număr limitat de sloturi pentru pluginuri și teme; sloturile utilizate sunt afișate în Setări după ce activezi Babilim.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Domeniul dat „%1$s” nu corespunde nici slug-ului propriu „%2$s” din manifestul pachetului, nici text_domain „%3$s”.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Indexul combinat pentru „%s” a fost reconstruit, dar indexul de traduceri nu l-a putut înregistra; următoarea reconstruire va reîncerca.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Textul original și traducerile realizate pe baza lui vor fi furnizate altor site-uri care instalează aceeași versiune.','The package declares no main translation file.'=>'Pachetul nu declară niciun fișier de traducere principal.','The package has no %s for its own text domain.'=>'Pachetul nu conține %s pentru propriul domeniu de text.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Tipul „%1$s” din manifestul pachetului nu corespunde tipului solicitat „%2$s”.','The package produced no servable main translation file.'=>'Pachetul nu a produs niciun fișier de traducere principal care poate fi servit.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Domeniul de text „%1$s” al pachetului nu corespunde celui al copiei componentei de pe acest site („%2$s”), așa că pachetul nu a fost instalat.','The packaged component could not be read.'=>'Componenta împachetată nu a putut fi citită.','The registration challenge is not in the expected form.'=>'Provocarea de înregistrare nu are forma așteptată.','The report could not be sent.'=>'Raportul nu a putut fi trimis.','The search could not be completed.'=>'Căutarea nu a putut fi finalizată.','The service asked this site to wait before syncing again.'=>'Serviciul a cerut acestui site să aștepte înainte de a se sincroniza din nou.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Serviciul nu a putut ajunge la site-ul dumneavoastră. Probabil un firewall, un plugin de securitate sau o regulă a gazdei blochează cererea; permiteți cererile către /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'Oferta de încărcare a serviciului era incompletă.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Domeniul de text „%1$s” (%2$s) este deja servit pentru o altă componentă instalată (%3$s); nu s-a instalat nimic.','The upload is kept until you ask Babilim to delete it.'=>'Încărcarea este păstrată până când îi cereți Babilim să o șteargă.','Theme'=>'Temă','Theme · %s'=>'Temă · %s','Themes'=>'Teme','There is no upload in progress.'=>'Nu există nicio încărcare în curs.','There is no upload waiting for confirmation.'=>'Nu există nicio încărcare în așteptarea confirmării.','These are the languages this site uses. You can change them in %s.'=>'Acestea sunt limbile pe care le folosește acest site. Le puteți modifica în %s.','These fields will be sent:'=>'Aceste câmpuri vor fi trimise:','This build is not one this site currently knows about for this component/locale.'=>'Această versiune nu este una pe care site-ul o cunoaște în prezent pentru această componentă/localizare.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Această componentă nu declară un număr de versiune, deci nu se poate solicita o traducere pentru ea.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Această componentă este mai mare decât acceptă serviciul, deci nu poate fi încărcată.','This component was already uploaded. Babilim is checking it now.'=>'Această componentă a fost deja încărcată. Babilim o verifică acum.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Numărul versiunii acestei componente are mai mult de %d caractere, lucru pe care Babilim nu îl poate gestiona, deci nu se poate solicita o traducere pentru ea.','This issues a new restore code and the previous one stops working. Continue?'=>'Aceasta emite un nou cod de restaurare, iar cel anterior nu va mai funcționa. Continuați?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Această rețea are prea multe site-uri pentru a fi verificate unul câte unul, iar unele dintre ele pot fi setate să șteargă identitatea lor Babilim la ștergerea pluginului. Licența plătită asociată unui astfel de site nu ar mai putea fi restaurată automat; ar trebui să contactați Asistență Babilim la %s. Pentru a păstra identitățile, apăsați Anulează, debifați „Șterge toate datele Babilim la dezinstalare” în Setări Babilim ale fiecărui site și dezactivați din nou. Dezactivați oricum?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Versiunea acestui plugin, pentru ca serviciul să vă poată spune să îl actualizați dacă este prea veche pentru a comunica cu el.','This report does not name a valid plugin or theme and locale.'=>'Acest raport nu conține un Nume valid de plugin sau temă și o limbă validă.','This report does not name an installed string.'=>'Acest raport nu specifică numele unui șir instalat.','This report is missing a valid build to report against.'=>'Acestui raport îi lipsește o versiune validă la care să se raporteze.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Acest raport va fi publicat public pe GitHub și poate fi păstrat de terți.','This restore code was not recognised for this site.'=>'Acest cod de restaurare nu a fost recunoscut pentru acest site.','This site already has an active registration that can no longer be recovered automatically.'=>'Acest site are deja o înregistrare activă care nu mai poate fi recuperată automat.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Acest site are %1$d componente în %2$d limbi, ceea ce necesită %3$d loturi de verificare; Babilim poate gestiona cel mult %4$d per execuție. Reduceți limbile gestionate în Setări sau dezactivați pluginurile și temele neutilizate, apoi apăsați Verifică din nou acum.','This site has no purchase to show a code for.'=>'Acest site nu are nicio achiziție pentru care să se afișeze un cod.','This site is already licensed. Reload the page.'=>'Acest site are deja licență. Reîncarcă pagina.','This site is not registered with Babilim yet.'=>'Acest site nu este încă înregistrat la Babilim.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Acest site depășește dimensiunea acceptată de serviciu la o singură sincronizare, așa că unele elemente au fost omise: %1$d componente și %2$d limbi.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Acest site face parte dintr-o rețea multisite, care nu instalează automat traduceri noi. Traducerile deja instalate sunt în continuare actualizate.','This site is verified.'=>'Acest site este verificat.','This site must be verified first.'=>'Mai întâi trebuie verificat acest site.','This site\'s URL, so the service can verify you own it.'=>'URL-ul acestui site, pentru ca serviciul să poată verifica faptul că îl dețineți.','This site\'s address is too long for Babilim to register.'=>'Adresa acestui site este prea lungă pentru a fi înregistrată de Babilim.','This site\'s configured locale.'=>'Setarea regională configurată pentru acest site.','This site\'s locale code is not one Babilim can register.'=>'Codul de localizare al acestui site nu este unul pe care Babilim îl poate înregistra.','This string can\'t be reported from this site.'=>'Acest șir nu poate fi raportat de pe acest site.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Acest șir nu se află printre traducerile instalate pe acest site. Căutați din nou și alegeți-l din listă.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Această traducere a fost actualizată de la căutarea dvs. Căutați din nou și alegeți șirul din noua listă.','To translate this component, Babilim needs its source.'=>'Pentru a traduce această componentă, Babilim are nevoie de sursa ei.','Too many attempts. Try again tomorrow.'=>'Prea multe încercări. Încercați din nou mâine.','Too many reports today. Try again tomorrow.'=>'Prea multe rapoarte astăzi. Încearcă din nou mâine.','Too many requests.'=>'Prea multe cereri.','Toolbar'=>'Bară de instrumente','Translating…'=>'Se traduce…','Translation does not load'=>'Traducerea nu se încarcă','Translation failed'=>'Traducerea a eșuat','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Fișierele de traducere pe care le pui în %s au întotdeauna prioritate față de cele Babilim. Sunt păstrate dacă nu debifezi această opțiune.','Translation requested.'=>'Traducere solicitată.','Translations'=>'Traduceri','Type'=>'Tip','Type at least 2 characters to search.'=>'Introduceți cel puțin 2 caractere pentru a căuta.','Unexpected HTTP %d response.'=>'Răspuns HTTP neașteptat %d.','Uninstall'=>'Dezinstalare','Unknown kind: %s'=>'Tip necunoscut: %s','Unsafe domain: %s'=>'Domeniu nesigur: %s','Unsafe locale: %s'=>'Localizare nesigură: %s','Unsafe slug: %s'=>'Slug nesigur: %s','Unsafe text_domain: %s'=>'text_domain nesigur: %s','Update'=>'Actualizează','Update available'=>'Actualizare disponibilă','Updates'=>'Actualizări','Updating…'=>'Se actualizează…','Upgrade this site'=>'Fă upgrade pentru acest site','Upload and request'=>'Încarcă și solicită','Upload cancelled.'=>'Încărcare anulată.','Upload complete — translation requested.'=>'Încărcare finalizată — traducere solicitată.','Upload expired before it finished'=>'Încărcarea a expirat înainte de finalizare','Upload in progress — continue or cancel'=>'Încărcare în curs — continuă sau anulează','Upload this component?'=>'Încarci această componentă?','Upload was not accepted'=>'Încărcarea nu a fost acceptată','Uploading'=>'Se încarcă','Uploading part %1$d of %2$d…'=>'Se încarcă partea %1$d din %2$d…','Uploading…'=>'Se încarcă…','Verified'=>'Verificat','Verify response was missing site_token.'=>'Răspunsului de verificare îi lipsea site_token.','Version %s'=>'Versiunea %s','What is sent when you enable Babilim'=>'Ce se trimite când activați Babilim','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Când ceva eșuează în Babilim, trimite un raport de eroare către Serviciul Babilim pentru a fi publicat ca problemă publică pe GitHub. Raportul este trimis ca provenind de la acest site, cu aceeași autentificare ca orice altă solicitare către Serviciul Babilim. Serviciul publică doar codul erorii și versiunile ca problemă publică pe GitHub; problema publică nu conține adresa site-ului, conținut sau căi de fișiere. Dezactivat implicit.','Where you saw this (optional)'=>'Unde ai văzut asta (opțional)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Cât timp această opțiune este activată, traducerile pe care serviciul le listează ca disponibile pentru limbile pe care le gestionezi sunt instalate în timpul sincronizării de două ori pe zi.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Greșit pentru acest context','Wrong meaning'=>'Sens greșit','Wrong plural form'=>'Formă de plural greșită','Wrong term'=>'Termen greșit','Yes'=>'Da','You are not allowed to do this.'=>'Nu ai permisiunea de a face acest lucru.','Your PHP version, for compatibility.'=>'Versiunea dvs. de PHP, pentru compatibilitate.','Your WordPress version, to serve compatible translation files.'=>'Versiunea dvs. de WordPress, pentru a livra fișiere de traducere compatibile.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Noul dvs. cod de restaurare: %s. Păstrați-l într-un loc sigur — codul anterior nu mai funcționează.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Raportul tău este procesat automat de modele AI și poate îmbunătăți această traducere pentru alte site-uri.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Site-ul dumneavoastră a răspuns, dar nu cu ceea ce era așteptat. API-ul REST poate fi rescris de un alt plugin sau acel endpoint poate fi păstrat în cache; excludeți /wp-json/babilim/v1/challenge din cache și din rescriere.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Site-ul dumneavoastră a răspuns prea greu. Încercați din nou mai târziu și verificați că gazda nu este prea lentă sau suprasolicitată.','Zip has no manifest.json.'=>'Arhiva zip nu conține manifest.json.','Zip is missing expected default file: %s'=>'Arhivei zip îi lipsește fișierul așteptat pentru domeniul „default”: %s','Zip is missing expected file: %s'=>'Arhivei zip îi lipsește fișierul așteptat: %s','_manifest.json has an unexpected structure'=>'_manifest.json are o structură neașteptată','could not read _manifest.json: %s'=>'nu s-a putut citi _manifest.json: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest lipsește sau are un „%s” nevalid.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'„server_build_id” din expected_manifest nu este un identificator de versiune build valid.','failed to parse _manifest.json: %s'=>'nu s-a putut analiza _manifest.json: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'ar deveni orfane %1$d din %2$d componente gestionate (mai mult de jumătate)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'ar deveni orfane toate componentele gestionate de tip %1$s (%2$d din %2$d)','l10n.php entry count mismatch for %s'=>'Numărul de intrări l10n.php nu concordă pentru %s','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json are un „default_domain_entries” nevalid.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json are un „default_domain_files” nevalid.','manifest.json in the zip is not valid JSON.'=>'manifest.json din arhiva zip nu este JSON valid.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json lipsește sau are un „%s” nevalid.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json lipsește sau are un „build_no” nevalid.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json lipsește sau are un „entries” nevalid.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json lipsește sau are un „extra_domains” nevalid.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json lipsește sau are un „files” nevalid.','manifest.json\'s \'%s\' does not match the expected value.'=>'Câmpul „%s” din manifest.json nu corespunde valorii așteptate.','manifest.json\'s \'contract\' is not a valid version string.'=>'„contract” din manifest.json nu este un șir de versiune valid.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'„kind” din manifest.json trebuie să fie „plugin” sau „theme”.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'„server_build_id” din manifest.json nu este un identificator de versiune build valid.','manifest.json\'s \'status\' must be \'published\'.'=>'Câmpul „status” (Stare) din manifest.json trebuie să aibă valoarea „published” (Publicat).','nonce must be a hexadecimal string.'=>'nonce trebuie să fie un șir hexazecimal.','per day'=>'pe zi','rc_…'=>'rc_…','sha256 mismatch for %s'=>'neconcordanță sha256 pentru %s','sha256 mismatch for default/%s'=>'neconcordanță sha256 pentru default/%s','component kind in the sweep brake messageplugin'=>'plugin','component kind in the sweep brake messagetheme'=>'temă','problem report categoryOther'=>'Altele','translation statusAvailable'=>'Disponibil','translation statusInstalled'=>'Instalată']];